import unittest

from textkit.cli import main
from textkit.topwords import top_words


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class TopWordsTest(unittest.TestCase):
    def test_counts_case_insensitively(self):
        self.assertEqual(top_words("The the THE cat", 2), [("the", 3), ("cat", 1)])

    def test_splits_on_non_letters(self):
        self.assertEqual(top_words("don't stop, don't-stop 2 times", 3),
                         [("don", 2), ("stop", 2), ("t", 2)])

    def test_sorts_by_count_then_alphabetically(self):
        self.assertEqual(top_words("b a b c a b", 3), [("b", 3), ("a", 2), ("c", 1)])
        self.assertEqual(top_words("z y x", 3), [("x", 1), ("y", 1), ("z", 1)])

    def test_fewer_distinct_words_than_k_returns_all(self):
        self.assertEqual(top_words("hi hi", 5), [("hi", 2)])

    def test_empty_or_no_letters(self):
        self.assertEqual(top_words("", 3), [])
        self.assertEqual(top_words("123 !? 4-5", 3), [])

    def test_non_ascii_letters_are_separators(self):
        # The Kelvin sign lower-cases to ASCII "k", but it is not an ASCII letter.
        self.assertEqual(top_words("Kéa", 3), [("a", 1)])

    def test_k_below_one_raises(self):
        with self.assertRaises(ValueError):
            top_words("a b", 0)
        with self.assertRaises(ValueError):
            top_words("a b", -2)


