    def test_k_zero_exits_2(self):
        code, out, err = run("top", "x", "--k", "0")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_non_numeric_k_exits_2(self):
        code, out, err = run("top", "x", "--k", "many")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))


